function money(cents, code) { integer(cents, 'money in cents'); return code + ' ' + (cents / 100).toFixed(2); }
function list(value, label, min = 1, max = 100) { ok(Array.isArray(value) && value.length >= min && value.length <= max, label + ' must contain ' + min + ' to ' + max + ' entries'); return value; }
